"""Generate a linker-retained receipt from the browser-test compile inputs."""

from hashlib import sha256
import json
from pathlib import Path
import sys


def main(output, inputs):
    sources = {path.name: sha256(path.read_bytes()).hexdigest() for path in inputs}
    if len(sources) != len(inputs):
        raise ValueError("Browser-test receipt source names must be unique")
    record = json.dumps(sources, sort_keys=True, separators=(",", ":"))
    output.write_text(
        "// Generated by write_source_receipt.py.\n"
        "[[gnu::used, gnu::retain, gnu::section(\"__TEXT,__barktestsrc\")]]\n"
        f"const char kBarkBrowserTestSources[] = {json.dumps(record)};\n"
    )


if __name__ == "__main__":
    main(Path(sys.argv[1]), [Path(value) for value in sys.argv[2:]])
